use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let t1_handle = thread::spawn(move || {
        // Worker t1: acquire both locks in a fixed order to avoid deadlock
        let _guard_a = a1.lock().unwrap();
        let _guard_b = b1.lock().unwrap();
        // Critical work done while holding both locks
        drop(_guard_b);
        drop(_guard_a);
        1
    });

    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);
    let t2_handle = thread::spawn(move || {
        // Worker t2: acquire both locks in the same fixed order to avoid deadlock
        let _guard_a = a2.lock().unwrap();
        let _guard_b = b2.lock().unwrap();
        // Critical work done while holding both locks
        drop(_guard_b);
        drop(_guard_a);
        1
    });

    let r1 = t1_handle.join().unwrap();
    let r2 = t2_handle.join().unwrap();

    println!("DONE t1={} t2={}", r1, r2);
}
